"""Read a directory into a deterministic file inventory."""

import hashlib
import os
from pathlib import Path
import stat


def _raise_walk_error(error: OSError) -> None:
    raise error


def _lstat_checked(path: Path, *, expect_dir: bool) -> os.stat_result:
    """lstat path, rejecting symbolic links and non-ordinary file types."""
    try:
        st = path.lstat()
    except OSError as error:
        raise ValueError(f"cannot stat {path}: {error}") from error
    mode = st.st_mode
    if stat.S_ISLNK(mode):
        raise ValueError(f"symbolic links are not supported: {path}")
    if expect_dir:
        if not stat.S_ISDIR(mode):
            raise ValueError(f"expected a directory: {path}")
    elif not stat.S_ISREG(mode):
        raise ValueError(f"expected an ordinary file: {path}")
    return st


def _identity(kind: str, st: os.stat_result) -> tuple:
    return (kind, st.st_dev, st.st_ino, st.st_size, st.st_mtime_ns)


def stat_snapshot(directory: str | Path) -> dict[str, tuple]:
    """Return an identity/metadata snapshot of every entry in directory.

    Maps '/'-separated paths relative to directory (``.`` for the root)
    to ``(kind, st_dev, st_ino, st_size, st_mtime_ns)`` tuples, where
    kind is ``"dir"`` or ``"file"``. Symbolic links and special files are
    rejected. Two equal snapshots prove the tree kept the same entries,
    file identities (``(dev, ino)``), sizes and modification times across
    a scan: a replacement created by rename cannot hide behind an
    unchanged path.
    """
    root = Path(directory)
    root_st = _lstat_checked(root, expect_dir=True)
    snapshot = {".": _identity("dir", root_st)}
    for current, subdirs, filenames in os.walk(root, onerror=_raise_walk_error):
        for name in subdirs:
            child = Path(current) / name
            st = _lstat_checked(child, expect_dir=True)
            snapshot[child.relative_to(root).as_posix()] = _identity("dir", st)
        for name in filenames:
            path = Path(current) / name
            st = _lstat_checked(path, expect_dir=False)
            snapshot[path.relative_to(root).as_posix()] = _identity("file", st)
    return snapshot


def inventory(directory: str | Path) -> list[dict[str, str | int]]:
    """Return path, size and SHA-256 for every ordinary file in directory."""
    root = Path(directory)
    _lstat_checked(root, expect_dir=True)

    records: list[dict[str, str | int]] = []
    for current, subdirs, filenames in os.walk(root, onerror=_raise_walk_error):
        for name in subdirs:
            _lstat_checked(Path(current) / name, expect_dir=True)
        for name in filenames:
            path = Path(current) / name
            _lstat_checked(path, expect_dir=False)
            digest = hashlib.sha256()
            size = 0
            # O_NOFOLLOW: refuse to follow a link swapped in after the lstat.
            flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
            try:
                fd = os.open(path, flags)
            except OSError as error:
                raise ValueError(f"cannot read {path}: {error}") from error
            with os.fdopen(fd, "rb", closefd=True) as source:
                for chunk in iter(lambda: source.read(1024 * 1024), b""):
                    digest.update(chunk)
                    size += len(chunk)
            records.append({
                "path": path.relative_to(root).as_posix(),
                "size": size,
                "sha256": digest.hexdigest(),
            })

    return sorted(records, key=lambda record: str(record["path"]))

"""Offline public-key trust store and trusted verification.

The store is a versioned JSON document holding, per key id (the
lowercase SHA-256 hex of a key's DER SubjectPublicKeyInfo), the PEM
public key and an ``active``/``revoked`` status with a revocation
reason. Mutations are atomic (synced temp file plus one ``os.replace``),
re-importing an active key is idempotent, and a revoked key can never
be restored.
"""

import json
from pathlib import Path

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives.serialization import (
    Encoding,
    PublicFormat,
)

from .seal import (
    ALGORITHM,
    TRUST_STORE_KIND,
    SealError,
    canonical_payload,
    decode_public_key,
    diff_inventory,
    guarded_inventory,
    is_key_id,
    key_id_of,
    load_manifest,
    load_public_key,
    publish_replace,
    require_outside,
)

STORE_VERSION = 1
ACTIVE = "active"
REVOKED = "revoked"

REASON_UNKNOWN_KEY = "unknown_key"
REASON_REVOKED = "revoked"
REASON_INVALID_SIGNATURE = "invalid_signature"
REASON_FILE_MISMATCH = "file_mismatch"

MAX_REASON_LENGTH = 1024


def _entry(pem: str, status: str, reason: str | None) -> dict:
    return {
        "public_key_pem": pem,
        "status": status,
        "revoked_reason": reason,
    }


def _new_store() -> dict:
    return {
        "kind": TRUST_STORE_KIND,
        "version": STORE_VERSION,
        "algorithm": ALGORITHM,
        "keys": {},
    }


def _validate_store(document: object, path: Path) -> dict:
    if not isinstance(document, dict):
        raise SealError(f"trust store must be a JSON object: {path}")
    if document.get("kind") != TRUST_STORE_KIND:
        raise SealError(f"not a release seal trust store: {path}")
    version = document.get("version")
    if not isinstance(version, int) or isinstance(version, bool):
        raise SealError(f"trust store field 'version' must be an integer: {path}")
    if version < 1 or version > STORE_VERSION:
        raise SealError(
            f"trust store version {version} is not supported "
            f"(supported: {STORE_VERSION}): {path}"
        )
    if document.get("algorithm") != ALGORITHM:
        raise SealError(f"trust store field 'algorithm' must be {ALGORITHM!r}: {path}")
    keys = document.get("keys")
    if not isinstance(keys, dict):
        raise SealError(f"trust store field 'keys' must be an object: {path}")
    for stored_id, record in keys.items():
        if not is_key_id(stored_id):
            raise SealError(f"trust store holds an invalid key id: {path}")
        if not isinstance(record, dict) or set(record) != {
            "public_key_pem",
            "status",
            "revoked_reason",
        }:
            raise SealError(f"trust store entry {stored_id} is malformed: {path}")
        pem = record["public_key_pem"]
        status = record["status"]
        reason = record["revoked_reason"]
        if not isinstance(pem, str) or status not in (ACTIVE, REVOKED):
            raise SealError(f"trust store entry {stored_id} is malformed: {path}")
        if reason is not None and not isinstance(reason, str):
            raise SealError(f"trust store entry {stored_id} is malformed: {path}")
        try:
            key = decode_public_key(pem.encode("ascii"), where=str(path))
        except SealError as error:
            raise SealError(
                f"trust store entry {stored_id} holds an invalid public key: {path}"
            ) from error
        if key_id_of(key) != stored_id:
            raise SealError(
                f"trust store entry {stored_id} does not match its key id: {path}"
            )
    return document


def load_store(path: Path) -> dict:
    try:
        raw = path.read_text(encoding="utf-8")
    except OSError as error:
        raise SealError(f"cannot read trust store {path}: {error}") from error
    try:
        document = json.loads(raw)
    except (json.JSONDecodeError, ValueError) as error:
        raise SealError(f"trust store is not UTF-8 JSON: {path}: {error}") from error
    return _validate_store(document, path)


def _write_store(path: Path, document: dict) -> None:
    data = (
        json.dumps(document, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    ).encode("utf-8")
    publish_replace(path, data, hint="trust-store")


def normalize_reason(reason: str | None) -> str | None:
    if reason is None:
        return None
    reason = reason.strip()
    return reason or None


def import_key(public_path, store_path) -> dict:
    """Import a PEM Ed25519 public key into the store.

    Importing an already-active key is idempotent and rewrites nothing.
    A revoked key is never revived: the call fails with status 2 and
    the store is left untouched.
    """
    public_path = Path(public_path)
    store_path = Path(store_path)
    key = load_public_key(public_path)
    key_id = key_id_of(key)
    pem = key.public_bytes(
        Encoding.PEM, PublicFormat.SubjectPublicKeyInfo
    ).decode("ascii")

    if store_path.exists():
        document = load_store(store_path)
        existing = document["keys"].get(key_id)
        if existing is not None:
            if existing["status"] == REVOKED:
                raise SealError(
                    f"key {key_id} is revoked in {store_path}; a revoked key "
                    "cannot be imported again"
                )
            return {"key_id": key_id, "status": ACTIVE, "changed": False}
        document["keys"][key_id] = _entry(pem, ACTIVE, None)
    else:
        document = _new_store()
        document["keys"][key_id] = _entry(pem, ACTIVE, None)
    _write_store(store_path, document)
    return {"key_id": key_id, "status": ACTIVE, "changed": True}


def revoke_key(store_path, key_id, reason: str | None = None) -> dict:
    """Mark a key revoked with an optional reason.

    Revoking an unknown key fails with status 2. Revoking an already
    revoked key is an idempotent no-op: the original revocation record
    (including its reason) is preserved.
    """
    store_path = Path(store_path)
    if not is_key_id(key_id):
        raise SealError(f"not a key id (64 lowercase hex digits): {key_id!r}")
    if not store_path.exists():
        raise SealError(f"trust store does not exist: {store_path}")
    reason = normalize_reason(reason)
    if reason is not None and len(reason) > MAX_REASON_LENGTH:
        raise SealError(
            f"revocation reason must be at most {MAX_REASON_LENGTH} characters"
        )
    document = load_store(store_path)
    record = document["keys"].get(key_id)
    if record is None:
        raise SealError(f"unknown key id in trust store: {key_id}")
    if record["status"] == REVOKED:
        return {
            "key_id": key_id,
            "status": REVOKED,
            "reason": record["revoked_reason"],
            "changed": False,
        }
    record["status"] = REVOKED
    record["revoked_reason"] = reason
    _write_store(store_path, document)
    return {
        "key_id": key_id,
        "status": REVOKED,
        "reason": reason,
        "changed": True,
    }


def _trusted_failure(key_id, reason: str) -> dict:
    return {
        "valid": False,
        "key_id": key_id,
        "reason": reason,
        "modified": [],
        "missing": [],
        "unexpected": [],
    }


def _stored_public_key(record: dict):
    return decode_public_key(
        record["public_key_pem"].encode("ascii"), where="trust store"
    )


def verify_trusted(directory, manifest_path, store_path) -> dict:
    """Verify a manifest against a directory using only the trust store.

    Version 2 manifests name their signer via ``key_id``; legacy
    version 1 manifests are matched against the store's keys. Failures
    always report ``valid: false`` with a stable ``reason`` and sorted
    file lists, never success.
    """
    directory = Path(directory)
    manifest_path = Path(manifest_path)
    store_path = Path(store_path)
    require_outside(directory, (manifest_path, store_path))
    document = load_store(store_path)
    version, files, signature, key_id = load_manifest(manifest_path)
    keys = document["keys"]

    if version == 2:
        record = keys.get(key_id)
        if record is None:
            return _trusted_failure(key_id, REASON_UNKNOWN_KEY)
        if record["status"] == REVOKED:
            return _trusted_failure(key_id, REASON_REVOKED)
        key = _stored_public_key(record)
        try:
            key.verify(signature, canonical_payload(version, key_id, files))
        except InvalidSignature:
            return _trusted_failure(key_id, REASON_INVALID_SIGNATURE)
        signer_id = key_id
    else:
        # Version 1 carries no key id: a revoked signer is reported as
        # revoked even before trying active keys; otherwise the unique
        # active key whose signature validates is the signer.
        for candidate_id, record in keys.items():
            if record["status"] != REVOKED:
                continue
            key = _stored_public_key(record)
            try:
                key.verify(signature, canonical_payload(version, None, files))
            except InvalidSignature:
                continue
            return _trusted_failure(candidate_id, REASON_REVOKED)
        signer_id = None
        for candidate_id, record in keys.items():
            if record["status"] != ACTIVE:
                continue
            key = _stored_public_key(record)
            try:
                key.verify(signature, canonical_payload(version, None, files))
            except InvalidSignature:
                continue
            signer_id = candidate_id
            break
        if signer_id is None:
            return _trusted_failure(None, REASON_UNKNOWN_KEY)

    modified, missing, unexpected = diff_inventory(
        files, guarded_inventory(directory)
    )
    if modified or missing or unexpected:
        return {
            "valid": False,
            "key_id": signer_id,
            "reason": REASON_FILE_MISMATCH,
            "modified": modified,
            "missing": missing,
            "unexpected": unexpected,
        }
    return {"valid": True, "key_id": signer_id}

"""Sign and verify a directory inventory with Ed25519.

Manifests exist in two versions:

* version 1 holds ``version``, ``algorithm``, ``hash``, ``files`` and
  ``signature``;
* version 2 adds ``key_id``, the lowercase SHA-256 hex of the signer's
  DER SubjectPublicKeyInfo.

The signature covers every field except ``signature``, serialized with
keys sorted, no whitespace and no Unicode escaping. Verification accepts
both versions; signing always emits version 2.
"""

import base64
import binascii
import errno
import hashlib
import json
import os
from pathlib import Path
import tempfile

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives.asymmetric.ed25519 import (
    Ed25519PrivateKey,
    Ed25519PublicKey,
)
from cryptography.hazmat.primitives.serialization import (
    Encoding,
    PublicFormat,
    load_pem_private_key,
    load_pem_public_key,
)

from .inventory import inventory, stat_snapshot

VERSION = 1
VERSION_CURRENT = 2
SUPPORTED_VERSIONS = (1, 2)
ALGORITHM = "Ed25519"
HASH = "SHA-256"
TRUST_STORE_KIND = "release-seal-trust-store"
V1_FIELDS = ("version", "algorithm", "hash", "files", "signature")
V2_FIELDS = ("version", "algorithm", "hash", "key_id", "files", "signature")

_PUBLIC_PEM_MARKERS = (b"-----BEGIN PUBLIC KEY-----", b"-----END PUBLIC KEY-----")
_PRIVATE_PEM_MARKERS = (b"-----BEGIN PRIVATE KEY-----", b"-----END PRIVATE KEY-----")


class SealError(ValueError):
    """A user-facing failure: print the message and exit with status 2."""


def key_id_of(key: Ed25519PublicKey) -> str:
    """Return the lowercase SHA-256 hex of a public key's DER SPKI."""
    der = key.public_bytes(Encoding.DER, PublicFormat.SubjectPublicKeyInfo)
    return hashlib.sha256(der).hexdigest()


def is_key_id(value: object) -> bool:
    return (
        isinstance(value, str)
        and len(value) == 64
        and all(char in "0123456789abcdef" for char in value)
    )


def canonical_payload(version: int, key_id: str | None, files: list[dict]) -> bytes:
    """Return the canonical UTF-8 JSON the signature covers.

    The signed body holds every manifest field except ``signature``
    (including ``key_id`` on version 2), with keys sorted, no whitespace
    and no Unicode escaping.
    """
    body: dict = {
        "version": version,
        "algorithm": ALGORITHM,
        "hash": HASH,
        "files": files,
    }
    if version >= 2:
        body["key_id"] = key_id
    return json.dumps(
        body, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")


def require_outside(directory: Path, paths: tuple[Path, ...]) -> None:
    root = directory.resolve()
    for path in paths:
        if path.resolve().is_relative_to(root):
            raise SealError(
                f"keys, manifests and trust stores must stay outside the "
                f"delivery tree: {path}"
            )


def load_private_key(path: Path) -> Ed25519PrivateKey:
    # The key is only read into memory for signing; it is never printed,
    # copied into the manifest or written anywhere else.
    try:
        data = path.read_bytes()
    except OSError as error:
        raise SealError(f"cannot read private key {path}: {error}") from error
    if not all(marker in data for marker in _PRIVATE_PEM_MARKERS):
        raise SealError(f"expected a PEM Ed25519 private key: {path}")
    try:
        key = load_pem_private_key(data, password=None)
    except Exception as error:
        raise SealError(f"cannot load PEM private key {path}: {error}") from error
    if not isinstance(key, Ed25519PrivateKey):
        raise SealError(f"expected an Ed25519 private key: {path}")
    return key


def load_public_key(path: Path) -> Ed25519PublicKey:
    try:
        data = path.read_bytes()
    except OSError as error:
        raise SealError(f"cannot read public key {path}: {error}") from error
    return decode_public_key(data, where=str(path))


def decode_public_key(data: bytes, *, where: str) -> Ed25519PublicKey:
    """Strictly decode a PEM Ed25519 SubjectPublicKeyInfo blob."""
    if not all(marker in data for marker in _PUBLIC_PEM_MARKERS):
        raise SealError(f"expected a PEM Ed25519 public key: {where}")
    try:
        key = load_pem_public_key(data)
    except Exception as error:
        raise SealError(f"cannot load PEM public key {where}: {error}") from error
    if not isinstance(key, Ed25519PublicKey):
        raise SealError(f"expected an Ed25519 public key: {where}")
    return key


def valid_record(record: object) -> bool:
    if not isinstance(record, dict):
        return False
    fields = set(record)
    if fields != {"path", "size", "sha256"}:
        return False
    size = record["size"]
    digest = record["sha256"]
    return (
        isinstance(record["path"], str)
        and record["path"] != ""
        and isinstance(size, int)
        and not isinstance(size, bool)
        and size >= 0
        and isinstance(digest, str)
        and len(digest) == 64
        and all(char in "0123456789abcdef" for char in digest)
    )


def load_manifest(path: Path) -> tuple[int, list[dict], bytes, str | None]:
    """Return (version, files, signature, key_id) from a manifest file."""
    try:
        raw = path.read_bytes()
    except OSError as error:
        raise SealError(f"cannot read manifest {path}: {error}") from error
    try:
        document = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise SealError(f"manifest is not UTF-8 JSON: {path}: {error}") from error
    if not isinstance(document, dict):
        raise SealError(f"manifest must be a JSON object: {path}")
    version = document.get("version")
    if (
        not isinstance(version, int)
        or isinstance(version, bool)
        or version not in SUPPORTED_VERSIONS
    ):
        supported = " or ".join(str(value) for value in SUPPORTED_VERSIONS)
        raise SealError(
            f"manifest field 'version' must be {supported}: {path}"
        )
    expected = set(V2_FIELDS if version == 2 else V1_FIELDS)
    if set(document) != expected:
        raise SealError(
            f"manifest version {version} must contain exactly "
            f"{', '.join(sorted(expected))}: {path}"
        )
    if document["algorithm"] != ALGORITHM:
        raise SealError(f"manifest field 'algorithm' must be {ALGORITHM!r}: {path}")
    if document["hash"] != HASH:
        raise SealError(f"manifest field 'hash' must be {HASH!r}: {path}")
    key_id = None
    if version == 2:
        key_id = document["key_id"]
        if not is_key_id(key_id):
            raise SealError(
                f"manifest field 'key_id' must be 64 lowercase hex digits: {path}"
            )
    files = document["files"]
    if not isinstance(files, list) or any(not valid_record(r) for r in files):
        raise SealError(f"manifest field 'files' holds invalid records: {path}")
    paths = [record["path"] for record in files]
    if len(set(paths)) != len(paths):
        raise SealError(f"manifest lists duplicate paths: {path}")
    signature = document["signature"]
    if not isinstance(signature, str):
        raise SealError(f"manifest field 'signature' must be Base64 text: {path}")
    try:
        decoded = base64.b64decode(signature, validate=True)
    except (binascii.Error, ValueError) as error:
        raise SealError(f"manifest signature is not Base64: {path}") from error
    if len(decoded) != 64:
        raise SealError(f"manifest signature must be 64 bytes: {path}")
    return version, files, decoded, key_id


def diff_inventory(expected: list[dict], actual: list[dict]) -> tuple[list, list, list]:
    expected_by_path = {record["path"]: record for record in expected}
    actual_by_path = {record["path"]: record for record in actual}
    common = expected_by_path.keys() & actual_by_path.keys()
    modified = sorted(
        path
        for path in common
        if (expected_by_path[path]["size"], expected_by_path[path]["sha256"])
        != (actual_by_path[path]["size"], actual_by_path[path]["sha256"])
    )
    missing = sorted(expected_by_path.keys() - actual_by_path.keys())
    unexpected = sorted(actual_by_path.keys() - expected_by_path.keys())
    return modified, missing, unexpected


def _looks_like_manifest(document: dict) -> bool:
    keys = set(document)
    if keys == set(V2_FIELDS) or keys == set(V1_FIELDS):
        return document.get("algorithm") == ALGORITHM
    return False


def _looks_like_trust_store(document: dict) -> bool:
    return document.get("kind") == TRUST_STORE_KIND and "keys" in document


def _read_nofollow(path: Path, max_bytes: int | None = None) -> bytes:
    """Read a regular file without ever following a swapped-in symlink."""
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    try:
        fd = os.open(path, flags)
    except OSError as error:
        raise SealError(f"cannot read {path}: {error}") from error
    with os.fdopen(fd, "rb") as source:
        if max_bytes is None:
            return source.read()
        return source.read(max_bytes)


def reject_forbidden_files(directory: Path, files: list[dict]) -> None:
    """Reject keys, manifests or trust stores placed inside the tree."""
    for record in files:
        rel = record["path"]
        path = directory / rel
        name = rel.rsplit("/", 1)[-1].lower()
        prefix = _read_nofollow(path, 256).lstrip()
        if name.endswith(".pem") or (
            prefix.startswith(b"-----BEGIN ") and b"KEY-----" in prefix[:80]
        ):
            raise SealError(f"keys must stay outside the delivery tree: {path}")
        if not name.endswith(".json"):
            continue
        try:
            document = json.loads(_read_nofollow(path).decode("utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(document, dict):
            continue
        if _looks_like_manifest(document):
            raise SealError(
                f"manifests must stay outside the delivery tree: {path}"
            )
        if _looks_like_trust_store(document):
            raise SealError(
                f"trust stores must stay outside the delivery tree: {path}"
            )


def guarded_inventory(directory: Path) -> list[dict]:
    """Inventory directory, proving it did not change during the scan.

    Identity snapshots taken before and after cover paths, file types,
    ``(dev, ino)`` identity, sizes and nanosecond mtimes. Every content
    read (hashing and forbidden-file classification) happens between the
    two snapshots, so a swapped or modified file is always caught. The
    tree is also refused if it contains keys, manifests or trust stores.
    """
    before = stat_snapshot(directory)
    files = inventory(directory)
    reject_forbidden_files(directory, files)
    after = stat_snapshot(directory)
    if before != after:
        raise SealError(f"directory changed while scanning: {directory}")
    return files


def _sync_directory(directory: Path) -> None:
    """fsync a directory; tolerate filesystems that reject it (EINVAL)."""
    fd = os.open(directory, os.O_RDONLY)
    try:
        os.fsync(fd)
    except OSError as error:
        if error.errno != errno.EINVAL:
            raise
    finally:
        os.close(fd)


def _staged_temp(parent: Path, hint: str, data: bytes) -> Path:
    """Write data to a synced hidden temp file in parent; fsync it."""
    fd, tmp_name = tempfile.mkstemp(
        prefix=f".{hint}.", suffix=".tmp", dir=parent
    )
    tmp = Path(tmp_name)
    try:
        os.fchmod(fd, 0o644)
