        except OSError as error:
            raise SealError(f"cannot publish manifest {target}: {error}") from error
        published = True
        try:
            _sync_directory(parent)
        except OSError as error:
            raise SealError(
                f"manifest published but directory sync failed: {target}: {error}"
            ) from error
    finally:
        if not published:
            tmp.unlink(missing_ok=True)
        else:
